import { loadFont } from "@remotion/google-fonts/Fredoka";
import React from "react";
import { AbsoluteFill, Easing, Img, interpolate, staticFile, useCurrentFrame } from "remotion";

// ZAAYNÚ (ficha CONVERT JA), vídeo 4: tutorial do app do ENTREGADOR (aceitar e concluir entrega). Voz Roberta, src/voz-entregador2-final.wav.
// Telas reais da gravação do cliente (video-1), com nome, telefone e endereço da cliente borrados (tools/borrar_telas.py).
// Tempos = relógio da voz; o vídeo tem LEAD de entrada.

const { fontFamily: F } = loadFont("normal", { weights: ["500", "600", "700"], subsets: ["latin", "latin-ext"] });

export const ENT_FPS = 30;
const LEAD = 0.2;
export const ENT_FRAMES = Math.round(58.0 * ENT_FPS);

const ORANGE = "#FC5500";
const PURPLE = "#652983";
const LILAC = "#F3F0FF";
const INK = "#2A1238";
const GREY = "#9C93A8";
const LINE = "#E2DCEB";
const WHITE = "#FFFFFF";
const SHADOW = "0 30px 70px rgba(42,18,56,0.18), 0 4px 14px rgba(42,18,56,0.08)";

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const BACK = Easing.out(Easing.back(1.25));
const INOUT = Easing.bezier(0.65, 0, 0.35, 1);
const k = (t: number, a: number, d = 0.4) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const pop = (t: number, a: number, d = 0.4) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: BACK });
const io = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], { ...cl, easing: INOUT });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
const mix = (a: number, b: number, p: number) => a + (b - a) * p;
const v = (s: string) => staticFile(`convert-ja/${s}`);

// trocas de cena
const FLOOD = 0.36;

const Flood: React.FC<{ t: number; at: number; x: number; y: number; bg: string; children: React.ReactNode }> = ({ t, at, x, y, bg, children }) => {
  const p = io(t, at, at + FLOOD);
  return <AbsoluteFill style={{ background: bg, clipPath: p >= 1 ? undefined : `circle(${(p * 2300).toFixed(1)}px at ${x}px ${y}px)` }}>{children}</AbsoluteFill>;
};

const Word: React.FC<{ t: number; at: number; children: string; color?: string }> = ({ t, at, children, color }) => {
  const e = k(t, at, 0.34);
  return (
    <span style={{ display: "inline-block", overflow: "hidden", padding: "0.04em 0.03em 0.14em", margin: "-0.04em 0 -0.14em", verticalAlign: "top" }}>
      <span style={{ display: "inline-block", color, transform: `translateY(${((1 - e) * 118).toFixed(2)}%)` }}>{children}</span>
    </span>
  );
};

type Linha = { txt: string; at: number; band?: string; color?: string; pad?: number };
const Tit: React.FC<{ t: number; top: number; from: number; to?: number; size: number; color: string; linhas: Linha[] }> = ({ t, top, from, to = 99, size, color, linhas }) => {
  if (t < from - 0.01 || t >= to) return null;
  return (
    <div style={{ position: "absolute", left: 120, right: 120, top, display: "flex", flexDirection: "column", alignItems: "center", gap: size * 0.16, fontFamily: F, fontWeight: 700, fontSize: size, lineHeight: 1.08, letterSpacing: "-0.015em", textAlign: "center", whiteSpace: "nowrap" }}>
      {linhas.map((l, i) => {
        const b = l.band ? k(t, l.at, 0.3) : 1;
        const pal = l.txt.split(" ");
        return (
          <div key={i} style={{ position: "relative", padding: l.band ? `${size * 0.03}px ${size * (l.pad ?? 0.3)}px ${size * 0.08}px` : 0 }}>
            {l.band ? <div style={{ position: "absolute", inset: 0, background: l.band, borderRadius: size * 0.26, transform: `scaleX(${b})` }} /> : null}
            <div style={{ position: "relative", display: "flex", gap: size * 0.24, justifyContent: "center" }}>
              {pal.map((w, j) => <Word key={j} t={t} at={l.at + j * 0.07} color={l.color ?? color}>{w}</Word>)}
            </div>
          </div>
        );
      })}
    </div>
  );
};

// logo em peças (mesmas peças do vídeo 1): o sorriso se desenha, as letras sobem, as pupilas olham em volta
const PIECES: [string, number, number][] = [["z", 0.09, 0.0], ["a1", 0.26, 0.05], ["a2", 0.45, 0.1], ["n", 0.77, 0.16], ["u", 0.92, 0.2], ["acento", 0.93, 0.26]];
const Logo: React.FC<{ t: number; at: number; w: number; white?: boolean }> = ({ t, at, w, white }) => {
  const h = (w * 545) / 1600;
  const flt = white ? "brightness(0) invert(1)" : undefined;
  const lay: React.CSSProperties = { position: "absolute", left: 0, top: 0, width: w, height: h, filter: flt };
  const sweep = io(t, at - 0.05, at + 0.38);
  const dt = t - at;
  const look = Math.sin(Math.max(0, dt - 0.5) * 3.4) * lin(t, at + 0.4, at + 0.8);
  const lookY = Math.cos(Math.max(0, dt - 0.5) * 1.3) * 0.4 * lin(t, at + 0.4, at + 0.8);
  const pu = pop(t, at + 0.22, 0.3);
  return (
    <div style={{ position: "relative", width: w, height: h }}>
      <Img src={v("logo-y.png")} style={{ ...lay, clipPath: `inset(0 ${(100 - mix(14, 72, sweep) * (sweep > 0 ? 1 : 0)).toFixed(2)}% 0 0)` }} />
      {PIECES.map(([n, cx, d]) => {
        const e = pop(t, at + d, 0.36);
        return <Img key={n} src={v(`logo-${n}.png`)} style={{ ...lay, opacity: e > 0 ? 1 : 0, transformOrigin: `${cx * 100}% 40%`, transform: `translateY(${((1 - e) * h * 0.2).toFixed(1)}px) scale(${(0.72 + 0.28 * e).toFixed(4)})` }} />;
      })}
      {["p1", "p2"].map((n) => (
        <Img key={n} src={v(`logo-${n}.png`)} style={{ ...lay, opacity: pu > 0 ? 1 : 0, transform: `translate(${(look * w * 0.015).toFixed(2)}px, ${(lookY * w * 0.009).toFixed(2)}px)` }} />
      ))}
    </div>
  );
};

// mascote: sobe de baixo com mola e respira devagar (só a imagem se move; texto fica parado)
const Mascote: React.FC<{ t: number; at: number; src: string; w: number; h: number; left: number; top: number; from?: "baixo" | "lado" | "pop"; mask?: string }> = ({ t, at, src, w, h, left, top, from = "baixo", mask }) => {
  const e = pop(t, at, 0.5);
  const resp = Math.sin((t - at) * 2.2) * 0.008 * lin(t, at + 0.5, at + 0.9);
  const dy = from === "baixo" ? (1 - e) * 900 : 0;
  const dx = from === "lado" ? (1 - e) * 700 : 0;
  const sc = from === "pop" ? 0.55 + 0.45 * e : 1;
  return (
    <Img src={v(src)} style={{ position: "absolute", left, top, width: w, height: h, opacity: from === "pop" ? Math.min(1, e * 3) : e > 0 ? 1 : 0, transformOrigin: from === "pop" ? "50% 15%" : "50% 100%", transform: `translate(${dx.toFixed(1)}px, ${dy.toFixed(1)}px) rotate(${((1 - e) * -6).toFixed(2)}deg) scale(${(sc * (1 + resp)).toFixed(4)})`, filter: "drop-shadow(0 30px 40px rgba(42,18,56,0.25))", WebkitMaskImage: mask }} />
  );
};

// chão em forma do sorriso do logo: esconde o corte de baixo da mascote (área sem texto da faixa do Instagram)
const Chao: React.FC<{ t: number; at: number; cor: string }> = ({ t, at, cor }) => {
  const e = k(t, at, 0.5);
  return (
    <svg width="1080" height="1920" viewBox="0 0 1080 1920" style={{ position: "absolute", inset: 0, transform: `translateY(${((1 - e) * 500).toFixed(1)}px)` }}>
      <path d="M-20 1500 Q540 1600 1100 1500 L1100 1940 L-20 1940 Z" fill={cor} />
    </svg>
  );
};


// ---------- celular com as telas do app (fotos da gravação, borradas) ----------
const PW = 574, PH = 1166, SW = 554, SH = 1146, PS = 0.72, PTOP = 610;
const PX = (1080 - PW * PS) / 2;
type Tela = { src: string; at: number; modo?: "corte" | "sobe" | "lado" };
const TELAS: Tela[] = [
  { src: "s1c", at: 0 },
  { src: "s2", at: 14.5, modo: "lado" },
  { src: "s3", at: 21.45, modo: "sobe" },
  { src: "s3b", at: 23.45, modo: "corte" },
  { src: "s3c", at: 24.25, modo: "corte" },
  { src: "s4a", at: 27.2, modo: "lado" },
  { src: "s4b", at: 34.05, modo: "corte" },
  { src: "s4c", at: 35.35, modo: "corte" },
  { src: "s5a", at: 38.9, modo: "lado" },
  { src: "s5c", at: 45.5, modo: "lado" },
  { src: "s6a", at: 47.55, modo: "corte" },
  { src: "s6b", at: 50.1, modo: "corte" },
  { src: "s6c", at: 50.4, modo: "corte" },
  { src: "s6d", at: 50.75, modo: "corte" },
];
// destaque: moldura laranja sobre uma parte da tela (coordenadas 0–1 da tela)
type Marca = { at: number; ate: number; x0: number; y0: number; x1: number; y1: number; redondo?: boolean };
const MARCAS: Marca[] = [
  { at: 15.7, ate: 17.3, x0: 0.03, y0: 0.185, x1: 0.97, y1: 0.36 },
  { at: 17.4, ate: 19.3, x0: 0.03, y0: 0.385, x1: 0.97, y1: 0.61 },
  { at: 24.6, ate: 27.0, x0: 0.03, y0: 0.09, x1: 0.97, y1: 0.145 },
  { at: 29.5, ate: 32.6, x0: 0.12, y0: 0.022, x1: 0.6, y1: 0.06 },
  { at: 34.15, ate: 35.1, x0: 0.07, y0: 0.44, x1: 0.93, y1: 0.49 },
  { at: 42.4, ate: 43.6, x0: 0.73, y0: 0.665, x1: 0.83, y1: 0.73, redondo: true },
  { at: 43.65, ate: 45.2, x0: 0.865, y0: 0.665, x1: 0.965, y1: 0.73, redondo: true },
  { at: 48.75, ate: 50.05, x0: 0.12, y0: 0.47, x1: 0.88, y1: 0.54 },
];
// toques (onde o dedo aperta)
const TOQUES: [number, number, number][] = [[14.35, 0.5, 0.43], [23.3, 0.5, 0.874], [33.9, 0.5, 0.834], [35.15, 0.63, 0.549], [41.6, 0.5, 0.93], [47.3, 0.5, 0.176], [51.6, 0.69, 0.42]];
// zoom por dentro da tela (a câmera chega perto sem o celular crescer para fora da área segura)
const ZOOMS: [number, number, number, number, number][] = [
  [15.55, 19.25, 0.3, 50, 32], [22.35, 23.45, 0.3, 50, 92], [29.3, 32.85, 0.4, 25, 2], [42.2, 45.4, 0.35, 85, 70], [48.6, 50.3, 0.25, 50, 50],
];
const zoomTela = (t: number) => {
  let z = 0, ox = 50, oy = 50;
  for (const [a, b, s, x, y] of ZOOMS) {
    if (t >= a - 0.1 && t <= b + 0.5) { z = s * (io(t, a, a + 0.45) - io(t, b - 0.05, b + 0.4)); ox = x; oy = y; }
  }
  return { z, ox, oy };
};

const Toque: React.FC<{ t: number; at: number; u: number; w: number }> = ({ t, at, u, w }) => {
  if (t < at - 0.22 || t > at + 0.3) return null;
  const e = k(t, at - 0.22, 0.16);
  const press = interpolate(t, [at - 0.04, at + 0.02, at + 0.12], [1, 0.82, 1], cl);
  const ring = lin(t, at, at + 0.28);
  const x = u * SW, y = w * SH;
  return (
    <>
      <div style={{ position: "absolute", left: x - 40, top: y - 40, width: 80, height: 80, borderRadius: 40, border: `5px solid ${ORANGE}`, opacity: (1 - ring) * (ring > 0 ? 0.8 : 0), transform: `scale(${1 + ring * 1.3})` }} />
      <div style={{ position: "absolute", left: x - 36, top: y - 36, width: 72, height: 72, borderRadius: 36, background: "rgba(252,85,0,0.45)", border: `5px solid ${WHITE}`, boxSizing: "border-box", opacity: e * (1 - lin(t, at + 0.18, at + 0.3)), transform: `scale(${(e * press).toFixed(3)})` }} />
    </>
  );
};

const Celular: React.FC<{ t: number; entra: number }> = ({ t, entra }) => {
  let i = 0;
  for (let j = 0; j < TELAS.length; j++) if (t >= TELAS[j].at) i = j;
  const cur = TELAS[i], prev = i > 0 ? TELAS[i - 1] : null;
  const prox = i + 1 < TELAS.length ? TELAS[i + 1].at : 52.6;
  // aproximação lenta e contínua em cada tela (imagem em movimento; os títulos ficam parados)
  const zb = 0.12 * lin(t, cur.at, prox);
  const flut = Math.sin(t * 1.3) * 7;
  const p = cur.modo === "corte" ? 1 : io(t, cur.at, cur.at + 0.32);
  const { z, ox, oy } = zoomTela(t);
  const img = (s: string, st: React.CSSProperties) => <Img key={s} src={v(`ent/${s}.jpg`)} style={{ position: "absolute", left: 0, top: 0, width: SW, height: SH, ...st }} />;
  const sai: React.CSSProperties = cur.modo === "sobe" ? { transform: `translateY(${(-p * SH).toFixed(1)}px)` } : { transform: `translateX(${(-p * SW * 0.35).toFixed(1)}px)`, opacity: 1 - p };
  const vem: React.CSSProperties = cur.modo === "sobe" ? { transform: `translateY(${((1 - p) * SH).toFixed(1)}px)` } : cur.modo === "lado" ? { transform: `translateX(${((1 - p) * SW).toFixed(1)}px)`, boxShadow: "-20px 0 40px rgba(0,0,0,0.15)" } : {};
  return (
    <div style={{ position: "absolute", left: PX, top: PTOP, width: PW * PS, height: PH * PS, opacity: Math.min(1, entra * 3), transform: `translateY(${flut.toFixed(1)}px) rotate(${((1 - entra) * 8 + Math.sin(t * 0.9) * 0.8).toFixed(2)}deg) scale(${(0.6 + 0.4 * entra).toFixed(4)})` }}>
      <div style={{ position: "absolute", left: 0, top: 0, width: PW, height: PH, borderRadius: 72, background: "#17101E", padding: 10, boxSizing: "border-box", boxShadow: SHADOW, transform: `scale(${PS})`, transformOrigin: "0 0" }}>
        <div style={{ position: "relative", width: SW, height: SH, borderRadius: 62, overflow: "hidden", background: WHITE }}>
          <div style={{ position: "absolute", inset: 0, transform: `scale(${(1 + z + zb).toFixed(4)})`, transformOrigin: `${ox}% ${oy}%` }}>
            {prev && p < 1 ? img(prev.src, sai) : null}
            {img(cur.src, vem)}
            {MARCAS.map((m, j) => {
              if (t < m.at || t > m.ate + 0.2) return null;
              const e = pop(t, m.at, 0.35) * (1 - lin(t, m.ate, m.ate + 0.2));
              return <div key={j} style={{ position: "absolute", left: m.x0 * SW, top: m.y0 * SH, width: (m.x1 - m.x0) * SW, height: (m.y1 - m.y0) * SH, borderRadius: m.redondo ? 999 : 22, border: `6px solid ${ORANGE}`, boxShadow: "0 0 24px rgba(252,85,0,0.35)", opacity: Math.min(1, e * 2), transform: `scale(${(1.15 - 0.15 * e).toFixed(3)})` }} />;
            })}
            {TOQUES.map(([at, u, w]) => <Toque key={at} t={t} at={at} u={u} w={w} />)}
          </div>
        </div>
        <div style={{ position: "absolute", left: PW / 2 - 66, top: 20, width: 132, height: 30, borderRadius: 15, background: "#17101E" }} />
      </div>
    </div>
  );
};

// selo do passo + título do passo (fica parado; uma frase sai inteira antes da próxima)
const Pilula: React.FC<{ t: number; at: number; n: number }> = ({ t, at, n }) => {
  const e = pop(t, at, 0.35);
  return (
    <div style={{ position: "absolute", left: 0, right: 0, top: 282, display: "flex", justifyContent: "center", opacity: e > 0 ? 1 : 0 }}>
      <div style={{ background: ORANGE, color: WHITE, fontFamily: F, fontWeight: 700, fontSize: 40, letterSpacing: "0.08em", padding: "8px 30px 10px", borderRadius: 40, transform: `scale(${e.toFixed(3)})`, display: "flex", alignItems: "center", gap: 22 }}>
        PASSO {n}
        <span style={{ display: "flex", gap: 9, alignItems: "center" }}>
          {[1, 2, 3, 4, 5, 6].map((j) => {
            const atual = j === n ? pop(t, at + 0.15, 0.35) : 0;
            const d = 14 + atual * 8;
            return <span key={j} style={{ width: d, height: d, borderRadius: d, background: WHITE, opacity: j <= n ? 1 : 0.38 }} />;
          })}
        </span>
      </div>
    </div>
  );
};

// ---------- passo 1: a notificação vai primeiro aos 3 mais próximos da loja ----------
const CX = 540, CY = 1050;
const MOTOS: [number, number, number][] = [[200, -40, 1], [200, 85, 1], [200, 205, 1], [380, -100, 2], [380, -15, 2], [380, 140, 2], [380, 25 + 180, 2], [380, 290, 2], [380, 60, 2]];
const Moto: React.FC<{ cor: string; s: number }> = ({ cor, s }) => (
  <svg width={s} height={s} viewBox="0 0 100 100">
    <circle cx="50" cy="50" r="48" fill={cor} />
    <g fill="none" stroke={WHITE} strokeWidth="6" strokeLinecap="round" strokeLinejoin="round">
      <circle cx="30" cy="64" r="9" /><circle cx="72" cy="64" r="9" />
      <path d="M30 64 H52 L60 44 H70 M60 44 L72 64 M40 64 L44 50 H56" />
      <rect x="22" y="38" width="18" height="14" rx="3" fill={WHITE} />
    </g>
  </svg>
);
const Loja: React.FC<{ s: number }> = ({ s }) => (
  <svg width={s} height={s} viewBox="0 0 100 100">
    <rect x="16" y="44" width="68" height="44" rx="6" fill={WHITE} stroke={PURPLE} strokeWidth="5" />
    <rect x="42" y="60" width="16" height="28" rx="3" fill={PURPLE} />
    <path d="M10 44 L18 18 H82 L90 44 Z" fill={ORANGE} />
    {[0, 1, 2, 3].map((i) => <path key={i} d={`M${10 + i * 20} 44 q10 12 20 0`} fill={i % 2 ? ORANGE : WHITE} stroke={ORANGE} strokeWidth="3" />)}
  </svg>
);
const CenaRaio: React.FC<{ t: number }> = ({ t }) => {
  const sai = io(t, 12.75, 13.25);
  const cam = 1.04 - k(t, 4.85, 0.8) * 0.04 + lin(t, 5.6, 12.7) * 0.04;
  const onda1 = lin(t, 7.6, 8.3), onda2 = lin(t, 11.5, 12.3);
  const recusa = lin(t, 10.3, 10.6);
  return (
    <AbsoluteFill style={{ transform: `scale(${(cam * (1 - sai * 0.6)).toFixed(4)})`, transformOrigin: `${CX}px ${CY}px`, opacity: 1 - sai }}>
      <svg width="1080" height="1920" viewBox="0 0 1080 1920" style={{ position: "absolute", inset: 0 }}>
        {[200, 380].map((r, i) => <circle key={r} cx={CX} cy={CY} r={r * k(t, 5.0 + i * 0.15, 0.6)} fill="none" stroke={LINE} strokeWidth="6" strokeDasharray="14 16" strokeDashoffset={(i ? -1 : 1) * t * 60} />)}
        {onda1 > 0 && onda1 < 1 ? <circle cx={CX} cy={CY} r={60 + onda1 * 170} fill="none" stroke={ORANGE} strokeWidth={10 * (1 - onda1) + 2} opacity={1 - onda1} /> : null}
        {onda2 > 0 && onda2 < 1 ? <circle cx={CX} cy={CY} r={220 + onda2 * 190} fill="none" stroke={ORANGE} strokeWidth={10 * (1 - onda2) + 2} opacity={1 - onda2} /> : null}
      </svg>
      <div style={{ position: "absolute", left: CX - 95, top: CY - 95, transform: `scale(${pop(t, 5.0, 0.45)})` }}><Loja s={190} /></div>
      {MOTOS.map(([r, ang, anel], i) => {
        const a = ((ang + (anel === 2 ? (t - 5) * 4 : (t - 5) * -3)) * Math.PI) / 180;
        const x = CX + r * Math.cos(a), y = CY + r * Math.sin(a);
        const e = pop(t, 5.5 + i * 0.07, 0.35);
        const liga = anel === 1 ? pop(t, 7.75 + i * 0.1, 0.3) * (1 - recusa * 0.85) : pop(t, 11.6 + (i - 3) * 0.08, 0.3);
        const cor = liga > 0.5 ? ORANGE : GREY;
        const s = 104;
        return (
          <div key={i} style={{ position: "absolute", left: x - s / 2, top: y - s / 2, transform: `scale(${(e * (1 + liga * 0.18)).toFixed(3)})`, filter: liga > 0.5 ? "drop-shadow(0 10px 18px rgba(252,85,0,0.35))" : "none" }}>
            <Moto cor={cor} s={s} />
            {anel === 1 && liga > 0.5 ? (
              <svg width="44" height="44" viewBox="0 0 44 44" style={{ position: "absolute", right: -10, top: -10, transform: `scale(${liga.toFixed(3)}) rotate(${(Math.sin(t * 18) * 12 * (1 - recusa)).toFixed(1)}deg)` }}>
                <circle cx="22" cy="22" r="21" fill={PURPLE} />
                <path d="M14 27 h16 l-2-3 v-6 a6 6 0 0 0 -12 0 v6 z M19 30 a3 3 0 0 0 6 0" fill={WHITE} />
              </svg>
            ) : null}
          </div>
        );
      })}
    </AbsoluteFill>
  );
};

// ---------- abertura e fechamento com a mascote ----------
const CenaAbertura: React.FC<{ t: number }> = ({ t }) => (
  <AbsoluteFill style={{ background: WHITE }}>
    <Tit t={t} top={330} from={-0.2} to={1.34} size={140} color={PURPLE} linhas={[{ txt: "Entregador,", at: -0.1 }]} />
    <Tit t={t} top={290} from={1.36} to={3.6} size={96} color={INK} linhas={[{ txt: "como aceitar", at: 1.38 }, { txt: "e concluir", at: 2.26, band: ORANGE, color: WHITE }, { txt: "uma entrega", at: 3.0 }]} />
    <Tit t={t} top={290} from={3.62} size={96} color={INK} linhas={[{ txt: "no app da", at: 3.64 }]} />
    {t >= 3.62 ? <div style={{ position: "absolute", left: 230, top: 420 }}><Logo t={t} at={4.0} w={620} /></div> : null}
    <Mascote t={t} at={0.15} src="masc-A-hero.png" w={595} h={720} left={243} top={852} from="pop" />
    <Chao t={t} at={0.05} cor={PURPLE} />
